component MeshBackground {
  ref canvas
  state time = 0

  mount {
    let ctx = canvas.getContext("2d")
    let width = canvas.width
    let height = canvas.height

    let animate = () => {
      time += 0.005
      ctx.fillStyle = `hsl(${200 + Math.sin(time) * 20}, 70%, 50%)`
      ctx.fillRect(0, 0, width, height)

      let gradient = ctx.createLinearGradient(0, 0, width, height)
      gradient.addColorStop(0, `hsl(${220 + Math.sin(time) * 30}, 80%, 60%)`)
      gradient.addColorStop(0.5, `hsl(${260 + Math.sin(time + 1) * 30}, 75%, 55%)`)
      gradient.addColorStop(1, `hsl(${200 + Math.sin(time + 2) * 30}, 70%, 50%)`)

      ctx.fillStyle = gradient
      ctx.fillRect(0, 0, width, height)

      requestAnimationFrame(animate)
    }
    animate()

    cleanup { }
  }

  column {
    canvas width=1920 height=1080 style="position: absolute; top: 0; left: 0; width: 100%; height: 100%;"
  }
}

