component Counter {
  state count = 0

  mount {
    let target = 12000
    let duration = 2000
    let startTime = Date.now()

    let animate = () => {
      let elapsed = Date.now() - startTime
      let progress = Math.min(elapsed / duration, 1)
      count = Math.floor(progress * target)

      if progress < 1 {
        requestAnimationFrame(animate)
      }
    }
    animate()
  }

  text `${count}+` style="font-size: 3.5rem; font-weight: bold; color: #60a5fa; margin: 0;"
}

