      gradient.addColorStop(0.5, `hsl(${260 + Math.sin(time + 1) * 30}, 75%, 55%)`)
      gradient.addColorStop(1, `hsl(${200 + Math.sin(time + 2) * 30}, 70%, 50%)`)

      ctx.fillStyle = gradient
      ctx.fillRect(0, 0, width, height)

      requestAnimationFrame(animate)
    }
    animate()
  }

