component Counter {
  state displayCount = 0

  mount {
    let target = 12000
    let duration = 2000
    let startTime = Date.now()
    let rafId = null

    let animate = () => {
      let elapsed = Date.now() - startTime
      let progress = Math.min(elapsed / duration, 1)
      displayCount = Math.floor(progress * target)

      if progress < 1 {
        rafId = requestAnimationFrame(animate)
      } else {
        displayCount = target
      }
    }
    animate()

    cleanup {
      if rafId != null {
        cancelAnimationFrame(rafId)
      }
    }
