          }`}
          style={{
            background:
              'linear-gradient(-45deg, #ee7752, #e73c7e, #23a6d5, #23d5ab)',
            backgroundSize: '400% 400%',
            animation: prefersReducedMotion ? 'none' : 'gradient-shift 15s ease infinite',
          }}
        />

