import { createSignal, onMount } from 'solid-js';

interface CardProps {
  title: string;
  description: string;
  delay: number;
}

export default function Card(props: CardProps) {
  const [isVisible, setIsVisible] = createSignal(false);

  const prefersReducedMotion = () => {
    return window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  };

  onMount(() => {
    const timer = setTimeout(() => {
      setIsVisible(true);
    }, props.delay * 300);

    return () => clearTimeout(timer);
  });

  return (
    <div
      class={`p-8 bg-gray-800 rounded-lg border border-gray-700 transition-all duration-700 ${
        !prefersReducedMotion()
          ? isVisible()
            ? 'opacity-100 translate-y-0'
            : 'opacity-0 translate-y-8'
          : 'opacity-100 translate-y-0'
      }`}
      style={{
        opacity: !prefersReducedMotion()
          ? isVisible()
            ? '1'
            : '0'
          : '1',
        transform: !prefersReducedMotion()
          ? isVisible()
            ? 'translateY(0)'
            : 'translateY(32px)'
          : 'translateY(0)',
        transition: !prefersReducedMotion()
          ? 'opacity 0.7s ease-out, transform 0.7s ease-out'
          : 'none',
      }}
    >
      <h3 class="text-2xl font-bold mb-3 text-white">{props.title}</h3>
      <p class="text-gray-300">{props.description}</p>
    </div>
  );
}

