import { createSignal, onMount, createEffect } from 'solid-js';

export default function UserCount() {
  const [count, setCount] = createSignal(0);
  const [isVisible, setIsVisible] = createSignal(false);
  const [hasStarted, setHasStarted] = createSignal(false);

  const prefersReducedMotion = () => {
    return window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  };

  onMount(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting && !hasStarted()) {
          setIsVisible(true);
          setHasStarted(true);
        }
      },
      { threshold: 0.5 }
    );

    const element = document.getElementById('user-count-section');
    if (element) {
      observer.observe(element);
    }

    return () => observer.disconnect();
  });

  createEffect(() => {
    if (!isVisible() || prefersReducedMotion()) return;

    const target = 12000;
    const duration = 2000; // 2 seconds
    const startTime = Date.now();

    const animate = () => {
      const elapsed = Date.now() - startTime;
      const progress = Math.min(elapsed / duration, 1);
      const currentCount = Math.floor(progress * target);

      setCount(currentCount);

      if (progress < 1) {
        requestAnimationFrame(animate);
      }
    };

    animate();
  });

  return (
    <div
      id="user-count-section"
      class="w-full py-20 px-4 bg-black"
    >
      <div class="max-w-4xl mx-auto text-center">
        <div class="text-6xl md:text-7xl font-bold text-white mb-4">
          {prefersReducedMotion() ? '12.000+' : `${count().toLocaleString('es-ES')}+`}
        </div>
        <p class="text-xl text-gray-400">Usuarios confían en Nimbus</p>
      </div>
    </div>
  );
}

