    <div class="relative w-full h-screen flex items-center justify-center overflow-hidden">
      <div class="absolute inset-0 hero-gradient"></div>

      <div class="relative z-10 text-center px-4">
        <h1 class="text-7xl md:text-8xl font-bold mb-4 tracking-tighter">
          Nimbus
        </h1>
        <p class="text-xl md:text-2xl text-gray-300 mb-8 max-w-2xl mx-auto">
          La plataforma cloud que transforma tu forma de trabajar
        </p>
        <button
          onMouseEnter={() => setIsHovered(true)}
          onMouseLeave={() => setIsHovered(false)}
          class={`px-8 py-3 bg-blue-500 hover:bg-blue-600 text-white font-semibold rounded-lg transition-all duration-300 ${
            isHovered() ? 'scale-110' : 'scale-100'
          }`}
        >
          Empezar
        </button>
      </div>
    </div>
  );
}

