import { createSignal, onMount } from 'solid-js';

interface CardProps {
  title: string;
  description: string;
  delay: number;
}

export default function Card(props: CardProps) {
  const [isVisible, setIsVisible] = createSignal(false);
  let cardRef: HTMLDivElement | undefined;

  onMount(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setTimeout(() => {
            setIsVisible(true);
          }, props.delay * 200);
          observer.unobserve(entry.target);
        }
      },
      { threshold: 0.1 }
    );

    if (cardRef) observer.observe(cardRef);
  });

  return (
    <div
      ref={cardRef}
      class={`p-8 bg-slate-800 rounded-lg border border-slate-700 hover:border-blue-500 transition-all duration-300 ${
        isVisible() ? 'card-visible' : 'card-hidden'
      }`}
    >
      <h3 class="text-2xl font-bold mb-4 text-blue-400">{props.title}</h3>
      <p class="text-gray-400">{props.description}</p>
    </div>
  );
}

