import { createSignal, onMount } from 'solid-js';

export default function Counter() {
  const [count, setCount] = createSignal(0);
  const [hasStarted, setHasStarted] = createSignal(false);
  let counterRef: HTMLDivElement | undefined;

  onMount(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting && !hasStarted()) {
          setHasStarted(true);
          animateCounter();
          observer.unobserve(entry.target);
        }
      },
      { threshold: 0.1 }
    );

    if (counterRef) observer.observe(counterRef);
  });

  const animateCounter = () => {
    const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    const duration = prefersReduced ? 0 : 2000;
    const target = 12000;
    const startTime = Date.now();

    const updateCount = () => {
      const elapsed = Date.now() - startTime;
      const progress = Math.min(elapsed / duration, 1);
      const currentCount = Math.floor(progress * target);
      setCount(currentCount);

      if (progress < 1) {
        requestAnimationFrame(updateCount);
      } else {
        setCount(target);
      }
    };

    if (prefersReduced) {
      setCount(target);
    } else {
      updateCount();
    }
  };

  return (
    <section ref={counterRef} class="py-24 px-4 bg-slate-950">
      <div class="max-w-4xl mx-auto text-center">
        <div class="counter-display text-7xl md:text-8xl font-bold text-blue-400 mb-4">
          {count().toLocaleString('es-ES')}+
        </div>
        <p class="text-2xl text-gray-300">Usuarios confían en Nimbus</p>
      </div>
    </section>
  );
}
